    "summary": "在华纳兄弟世界与您最喜爱的角色见面",
    "description": "华纳兄弟世界是全球最大的室内主题公园,DC漫画超级英雄与乐一通和汉纳巴伯拉的经典角色汇聚在一个壮观的屋檐下。六个主题区域——包括哥谭市、大都会和卡通枢纽——各自完美再现了其独特的宇宙,沉浸感极强。尽管是室内场馆,高耸的天花板和出色的灯光设计消除了任何局促感。与蝙蝠侠、超人和神奇女侠合影留念,或与兔八哥、崔弟和汤姆猫与杰瑞鼠重温童年回忆。主题餐厅的角色用餐体验更增添了一层魔力。整个公园保持完美的空调舒适环境,即使在盛夏也能尽情享受,使其成为从儿童到成人各年龄段游客的心爱目的地。",
